package com.miniforce.controller;
import com.miniforce.dto.*; import com.miniforce.dto.AdminDtos.*; import com.miniforce.dto.UserDtos.*; import com.miniforce.service.*; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/admin") public class AdminController {private final AdminService admin;private final UserService users;private final DiscussionService discussions;public AdminController(AdminService a,UserService u,DiscussionService d){admin=a;users=u;discussions=d;}@GetMapping("/dashboard") AdminDashboardResponse dashboard(){return admin.dashboard();}@GetMapping("/users") List<AdminUserResponse> users(@RequestParam(required=false)String search){return users.adminList(search);}@PutMapping("/users/{id}/role") AdminUserResponse role(@PathVariable Long id,@Valid @RequestBody UpdateRoleRequest r){return users.adminRole(id,r.role());}@DeleteMapping("/discussions/{id}") ResponseEntity<Void> deleteDiscussion(@PathVariable Long id){discussions.moderate(id);return ResponseEntity.noContent().build();}}
